<?php namespace App\Controllers\Api; use App\Models\OrderModel;
class Orders extends BaseApi {
 private function customer($db){$h=$this->request->getHeaderLine('Authorization');if(!preg_match('/Bearer\s+(.+)/i',$h,$m))return null;$raw=base64_decode(trim($m[1]),true);if(!$raw||!str_contains($raw,'|'))return null;[$em,$sig]=explode('|',$raw,2);$sec=getenv('ELORES_CUSTOMER_SECRET')?:'elores-customer-secret';if(!hash_equals(hash_hmac('sha256',$em,$sec),$sig))return null;return $db->table('customers')->where('email',$em)->get()->getRowArray();}
 public function track(){ $number=trim((string)$this->request->getGet('order_number'));$phone=preg_replace('/\D/','',(string)$this->request->getGet('phone'));if(!$number||strlen($phone)<10)return $this->ok(['message'=>'Order number and phone are required'],422);$db=db_connect();$o=$db->table('orders')->where('order_number',$number)->where('phone',$phone)->get()->getRowArray();if(!$o)return $this->ok(['message'=>'Order not found. Check order number and phone.'],404);$o['items']=$db->table('order_items')->where('order_id',$o['id'])->get()->getResultArray();return $this->ok(['data'=>$o]); }
 public function create(){try{$d=$this->json();foreach(['name','email','phone','address','city','state','pincode','payment_method','items'] as $k)if(empty($d[$k]))return $this->ok(['message'=>"$k is required"],422);$phone=preg_replace('/\D/','',$d['phone']);if(!preg_match('/^[0-9]{10}$/',$phone))return $this->ok(['message'=>'Enter a valid 10-digit phone number'],422);if(!preg_match('/^[0-9]{6}$/',$d['pincode']))return $this->ok(['message'=>'Enter a valid 6-digit pincode'],422);$db=db_connect();$cu=$this->customer($db);$customerId=$cu['id']??null;$subtotal=0;$items=[];foreach($d['items'] as $it){$p=$db->table('products')->where('id',(int)($it['product_id']??0))->where('active',1)->get()->getRowArray();if(!$p)continue;$qty=max(1,(int)($it['qty']??1));if((int)$p['stock']<$qty)return $this->ok(['message'=>$p['name'].' does not have enough stock'],422);$price=(float)($p['sale_price']?:$p['price']);$subtotal+=$price*$qty;$items[]=[$p,$qty,$price];}if(!$items)return $this->ok(['message'=>'No valid items'],422);$settings=$db->table('store_settings')->where('setting_key','free_shipping_min')->get()->getRowArray();$free=(float)($settings['setting_value']??999);$shipping=$subtotal>=$free?0:99;$discount=0;$coupon=null;if(!empty($d['coupon_code'])){$coupon=$db->table('coupons')->where('code',strtoupper($d['coupon_code']))->where('active',1)->get()->getRowArray();if(!$coupon||($coupon['expires_at']&&strtotime($coupon['expires_at'])<time())||$subtotal<(float)$coupon['min_order'])return $this->ok(['message'=>'Coupon is invalid, expired or minimum order not met'],422);$discount=$coupon['type']==='percent'?$subtotal*((float)$coupon['value']/100):min($subtotal,(float)$coupon['value']);}
 $number='EL'.date('ymd').strtoupper(substr(bin2hex(random_bytes(3)),0,5));$db->transBegin();$om=new OrderModel();$id=$om->insert(['order_number'=>$number,'name'=>$d['name'],'email'=>$d['email'],'phone'=>$phone,'address'=>$d['address'],'city'=>$d['city'],'state'=>$d['state'],'pincode'=>$d['pincode'],'payment_method'=>$d['payment_method'],'payment_status'=>'Pending','subtotal'=>$subtotal,'shipping'=>$shipping,'discount'=>round($discount,2),'coupon_code'=>$coupon['code']??null,'total'=>max(0,$subtotal+$shipping-$discount),'status'=>'Pending','customer_id'=>$customerId],true);if(!$id)throw new \RuntimeException('Unable to create order');foreach($items as [$p,$qty,$price]){$db->table('order_items')->insert(['order_id'=>$id,'product_id'=>$p['id'],'product_name'=>$p['name'],'price'=>$price,'qty'=>$qty,'line_total'=>$price*$qty]);$db->table('products')->where('id',$p['id'])->set('stock','GREATEST(stock-'.$qty.',0)',false)->update();}
 if($db->tableExists('notification_queue'))$db->table('notification_queue')->insertBatch([['channel'=>'email','recipient'=>$d['email'],'subject'=>'Elores order '.$number,'message'=>'Thank you. Your order '.$number.' has been received.','status'=>'queued','created_at'=>date('Y-m-d H:i:s')],['channel'=>'whatsapp','recipient'=>$phone,'subject'=>'Order confirmation','message'=>'Elores order '.$number.' has been received.','status'=>'queued','created_at'=>date('Y-m-d H:i:s')]]);if(!empty($d['session_key'])&&$db->tableExists('abandoned_carts'))$db->table('abandoned_carts')->where('session_key',$d['session_key'])->update(['recovered'=>1]);if($db->transStatus()===false){$db->transRollback();throw new \RuntimeException('Database transaction failed');}$db->transCommit();return $this->ok(['message'=>'Order placed','order_number'=>$number,'order_id'=>$id,'total'=>max(0,$subtotal+$shipping-$discount)],201);}catch(\Throwable $e){if(isset($db)&&$db->transStatus()===false)$db->transRollback();log_message('error','Order create failed: '.$e->getMessage());return $this->ok(['message'=>'Order could not be placed: '.$e->getMessage()],500);}}
}
